/* RunTag service worker — generated by scripts/sw/build-sw.mjs at build time. Do not edit public/sw.js. */
const BUILD_ID = '__BUILD_ID__'
const PRECACHE = __PRECACHE__
const CACHE = `runtag-shell-${BUILD_ID}`
const SHELL = '/shell'

self.addEventListener('install', (event) => {
  // Precache everything first; activation waits until the idle home view asks for it (M-9).
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(PRECACHE.map((url) => new Request(url, { cache: 'reload' })))),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k.startsWith('runtag-shell-') && k !== CACHE).map((k) => caches.delete(k))),
    ),
  )
})

const isShellPath = (p) => p === '/app' || p.startsWith('/app/') || p.startsWith('/t/')

self.addEventListener('fetch', (event) => {
  const req = event.request
  if (req.method !== 'GET') return
  const url = new URL(req.url)
  if (url.origin !== self.location.origin) return

  // App navigations: cache-first with the one shell document; path and query ignored, /t/* never cached.
  if (req.mode === 'navigate' && isShellPath(url.pathname)) {
    event.respondWith(
      caches.open(CACHE).then((cache) => cache.match(SHELL)).then((hit) => hit || fetch(req)),
    )
    return
  }
  // Build assets: cache-first from this build's cache. ignoreSearch: Next/Vercel append ?dpl=<deployment>.
  if (url.pathname.startsWith('/_next/static/') || PRECACHE.includes(url.pathname)) {
    event.respondWith(
      caches.open(CACHE).then((cache) => cache.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req))),
    )
  }
})

self.addEventListener('message', (event) => {
  const msg = event.data || {}
  if (msg.type === 'SKIP_WAITING') {
    self.skipWaiting()
  } else if (msg.type === 'STATUS') {
    const port = event.ports && event.ports[0]
    event.waitUntil(
      caches.open(CACHE).then(async (cache) => {
        const present = await Promise.all(PRECACHE.map((u) => cache.match(u).then(Boolean)))
        port && port.postMessage({ ready: present.every(Boolean), buildId: BUILD_ID, cache: CACHE })
      }),
    )
  }
})
